#include "lobby_scene.hpp"
#include "character_create.hpp"
#include "source_font.hpp"
#import <Metal/Metal.h>
#include <iostream>
void need(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
int main(int argc,char** argv){@autoreleasepool{try{
 [NSApplication sharedApplication];
 if(argc<2)throw std::runtime_error("Pass original client asset root");
 auto data=mu::lobby::load(argv[1]);if(data->placements.objects.size()!=375||data->camera.size()!=10||data->models.empty()||!data->triangles)throw std::runtime_error("Original World74 scene incomplete");
 auto view=[[MuLobbyScene alloc] initWithData:data];auto renderer=[SCNRenderer rendererWithDevice:MTLCreateSystemDefaultDevice() options:nil];renderer.scene=view.scene;renderer.pointOfView=view.pointOfView;
 auto initial=view.pointOfView.position;[view renderer:view updateAtTime:1];[view renderer:view updateAtTime:1.08];auto moved=view.pointOfView.position;if(initial.x==moved.x&&initial.y==moved.y)throw std::runtime_error("Original camera script did not advance");
 auto image=[renderer snapshotAtTime:0 withSize:CGSizeMake(1024,688) antialiasingMode:SCNAntialiasingModeMultisampling2X];if(!image)throw std::runtime_error("Lobby snapshot failed");
 NSBitmapImageRep* pixels=[[NSBitmapImageRep alloc] initWithData:image.TIFFRepresentation];unsigned visible=0;for(NSInteger y=0;y<pixels.pixelsHigh;y+=4)for(NSInteger x=0;x<pixels.pixelsWide;x+=4){auto c=[[pixels colorAtX:x y:y] colorUsingColorSpace:NSColorSpace.deviceRGBColorSpace];if(c.redComponent+c.greenComponent+c.blueComponent>.12)visible++;}
 if(argc>2){auto png=[pixels representationUsingType:NSBitmapImageFileTypePNG properties:@{}];[png writeToFile:[NSString stringWithUTF8String:argv[2]] atomically:YES];}
 std::cout<<"World74 objects="<<data->placements.objects.size()<<" models="<<data->models.size()<<" unique_triangles="<<data->triangles<<" camera_points="<<data->camera.size()<<" visible_samples="<<visible<<"\n";
 auto previews=mu::lobby::load_creation_previews(argv[1]);for(auto& pair:*previews)for(auto& visual:pair)if(!visual||visual->parts.empty()||!visual->idlePeriod)throw std::runtime_error("Original NewFace preview incomplete");
 mu::ui::prepare_source_font(argv[1],"Eng");auto panel=[[MuCharacterCreatePanel alloc] initWithRoot:argv[1] language:"Eng" previews:previews];panel.frame=NSMakeRect(0,0,800,600);[panel layoutSubtreeIfNeeded];[panel configureClassMask:0];std::vector<NSButton*> jobs;SCNView* face=nil;std::function<void(NSView*)> inspect=[&](NSView* parent){for(NSView* child in parent.subviews){if([child isKindOfClass:SCNView.class])face=(SCNView*)child;if([child isKindOfClass:NSButton.class]&&child.frame.size.width==108)jobs.push_back((NSButton*)child);inspect(child);}};inspect(panel);if(!face||jobs.size()!=7)throw std::runtime_error("Create UI is missing class buttons or NewFace preview");for(auto job:jobs)if(job.enabled!=(job.tag<3))throw std::runtime_error("Server class-card restriction mismatch");[panel configureClassMask:15];auto faceRenderer=[SCNRenderer rendererWithDevice:MTLCreateSystemDefaultDevice() options:nil];faceRenderer.scene=face.scene;faceRenderer.pointOfView=face.pointOfView;unsigned jobIndex=0;for(NSButton* job:jobs){[job performClick:nil];if(panel.selectedClass!=job.tag)throw std::runtime_error("Class button selected wrong class: expected "+std::to_string(job.tag)+" got "+std::to_string(panel.selectedClass));[face.delegate renderer:face updateAtTime:10+jobIndex];[face.delegate renderer:face updateAtTime:10.04+jobIndex];auto shot=[faceRenderer snapshotAtTime:0 withSize:CGSizeMake(410,335) antialiasingMode:SCNAntialiasingModeMultisampling2X];NSBitmapImageRep* rep=[[NSBitmapImageRep alloc] initWithData:shot.TIFFRepresentation];unsigned count=0;for(unsigned y=0;y<335;y+=4)for(unsigned x=0;x<410;x+=4){auto c=[[rep colorAtX:x y:y] colorUsingColorSpace:NSColorSpace.deviceRGBColorSpace];if(c.alphaComponent>.1&&c.redComponent+c.greenComponent+c.blueComponent>.1)count++;}if(count<20)throw std::runtime_error("Empty original NewFace preview class "+std::to_string(job.tag));if(argc>2)[[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}] writeToFile:[NSString stringWithFormat:@"%s.create-%ld.png",argv[2],(long)job.tag] atomically:YES];jobIndex++;}std::cout<<"Creation previews=7 class-card gates=PASS\n";
 auto characterData=mu::lobby::load(argv[1],{},75);if(characterData->placements.objects.empty()||characterData->models.empty())throw std::runtime_error("Missing World75 scene");mu::client::CharacterList list{};for(unsigned i=0;i<5;i++)list.characters.push_back({i,100,0,"Slot"+std::to_string(i),{0,255,255,255,255,0xF3,0,0,0,0xF8,0,0,0xF0,255,255,255,0,0}});auto characters=mu::lobby::load_characters(argv[1],list);if(characters.size()!=5||!characters.front().unsupported.empty())throw std::runtime_error("Naked DW appearance decoding mismatch");
 auto characterView=[[MuLobbyScene alloc] initWithData:characterData];[characterView setCharacters:characters];[characterView selectCharacter:0];[characterView renderer:characterView updateAtTime:1.];for(SCNNode* node in characterView.scene.rootNode.childNodes)if([node.name hasPrefix:@"character-row:"])need(std::abs(node.opacity-1.)<1e-6,"Unselected character was dimmed");[characterView selectCharacter:-1];[characterView renderer:characterView updateAtTime:1.1];for(SCNNode* node in characterView.scene.rootNode.childNodes)if([node.name hasPrefix:@"character-row:"])need(std::abs(node.opacity-1.)<1e-6,"Character faded when selection cleared");renderer.scene=characterView.scene;renderer.pointOfView=characterView.pointOfView;[characterView renderer:characterView updateAtTime:1];[characterView renderer:characterView updateAtTime:1.04];[characterView selectCharacter:2];[characterView renderer:characterView updateAtTime:1.08];auto selectedNode=[characterView.scene.rootNode childNodeWithName:@"character-row:2" recursively:NO];auto torso=selectedNode.position;torso.z+=110;auto screen=[characterView projectPoint:torso];if([characterView characterRowAtPoint:NSMakePoint(screen.x,screen.y)]!=2)throw std::runtime_error("Projected character pick returned wrong row");if([characterView characterRowAtPoint:NSMakePoint(-100,-100)]!=-1)throw std::runtime_error("Empty space selected a character");
 __block unsigned picked=99;__block BOOL enterRequested=NO;characterView.onCharacter=^(unsigned row,BOOL enter){picked=row;enterRequested=enter;};
 auto click=[&](NSInteger count,NSPoint p){return [NSEvent mouseEventWithType:NSEventTypeLeftMouseDown location:p modifierFlags:0 timestamp:0 windowNumber:0 context:nil eventNumber:0 clickCount:count pressure:1];};
 auto hit=NSMakePoint(screen.x,screen.y);[characterView mouseDown:click(1,hit)];if(picked!=2||enterRequested)throw std::runtime_error("Single click requested world entry instead of selection");
 [characterView mouseDown:click(2,hit)];if(picked!=2||!enterRequested)throw std::runtime_error("Double click did not request selected character entry");
 picked=99;[characterView mouseDown:click(1,NSMakePoint(-100,-100))];if(picked!=99)throw std::runtime_error("Empty click requested world entry");

 auto shot=[renderer snapshotAtTime:0 withSize:CGSizeMake(1024,688) antialiasingMode:SCNAntialiasingModeMultisampling2X];if(!shot)throw std::runtime_error("World75 rendering failed");if(argc>2){NSBitmapImageRep* rep=[[NSBitmapImageRep alloc] initWithData:shot.TIFFRepresentation];[[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}] writeToFile:[[NSString stringWithUTF8String:argv[2]] stringByAppendingString:@".characters.png"] atomically:YES];}
 std::cout<<"World75 objects="<<characterData->placements.objects.size()<<" models="<<characterData->models.size()<<" character_rigs="<<characters.size()<<"\n";
 if(visible<100)throw std::runtime_error("Camera produced an empty scene");[view setActive:NO];return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}}
